package com.csi;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.security.web.csrf.HttpSessionCsrfTokenRepository;import org.springframework.security.authentication.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.filter.OncePerRequestFilter;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Configuration public class Security {
 @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder(12);}
 @Bean UserDetailsService users(Db db){return name->{var rows=db.list("SELECT * FROM users WHERE username=?",name);if(rows.isEmpty())throw new UsernameNotFoundException("Unknown user");var u=rows.getFirst();return User.withUsername(name).password((String)u.get("passwordHash")).roles((String)u.get("role")).build();};}
 @Bean AuthenticationManager auth(UserDetailsService users,PasswordEncoder encoder){var p=new org.springframework.security.authentication.dao.DaoAuthenticationProvider(users);p.setPasswordEncoder(encoder);return new ProviderManager(p);}
 @Bean SecurityFilterChain chain(HttpSecurity http,@Value("${csi.internal-token}")String token)throws Exception{
 if(token.length()<32)throw new IllegalStateException("Internal token must be at least 32 characters");
 var internal=new OncePerRequestFilter(){protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(req.getRequestURI().startsWith("/internal/")){String provided=Optional.ofNullable(req.getHeader("Authorization")).orElse("");if(!MessageDigest.isEqual(("Bearer "+token).getBytes(StandardCharsets.UTF_8),provided.getBytes(StandardCharsets.UTF_8))){res.sendError(401);return;}SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("agent",null,List.of(new SimpleGrantedAuthority("ROLE_AGENT"))));}chain.doFilter(req,res);}};
 http.csrf(c->c.csrfTokenRepository(new HttpSessionCsrfTokenRepository()).ignoringRequestMatchers("/internal/**","/api/integrations/github/scan-results"))
 .authorizeHttpRequests(a->a.dispatcherTypeMatchers(jakarta.servlet.DispatcherType.ERROR).permitAll().requestMatchers("/api/auth/login","/api/auth/csrf","/api/health","/api/integrations/github/scan-results").permitAll().requestMatchers("/internal/**").hasRole("AGENT").requestMatchers("/api/**").hasRole("SECURITY_REVIEWER").anyRequest().denyAll())
 .exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401))).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.disable()).addFilterBefore(internal,UsernamePasswordAuthenticationFilter.class);
 return http.build();
 }
}
